1	/* ── TEAM ──────────────────────────── */
2	.team-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
3	
4	/* Board recruit card — sits below the team grid on /about → Team. v2 */
5	.board-recruit-card {
6	  margin-top: 36px;
7	  padding: 28px 32px;
8	  background: var(--bg-elevated);
9	  border: 1px solid var(--border);
10	  border-left: 4px solid var(--brand);
11	  border-radius: var(--radius-lg);
12	  display: flex; flex-direction: column; gap: 12px; align-items: flex-start;
13	  max-width: 720px;
14	}
15	.board-recruit-card h3 {
16	  font-family: var(--font-display);
17	  font-size: 1.25rem; font-weight: 700;
18	  letter-spacing: -.015em; color: var(--fg);
19	}
20	.board-recruit-card p {
21	  font-size: .98rem; line-height: 1.65; color: var(--fg-muted);
22	}
23	
24	/* Founder's Series — small list, no card imagery, anchored at the
25	   bottom of /about. Optional, low-key per v2. */
26	.founders-series-list {
27	  list-style: none; padding: 0; margin: 0; counter-reset: fs;
28	  border-top: 1px solid var(--border);
29	}
30	.founders-series-list li {
31	  display: flex; align-items: baseline; gap: 14px;
32	  padding: 16px 4px;
33	  border-bottom: 1px solid var(--border);
34	  counter-increment: fs;
35	}
36	.founders-series-list .fs-num {
37	  font-family: var(--font-display); font-size: .76rem; font-weight: 700;
38	  letter-spacing: .14em; color: var(--accent);
39	  flex-shrink: 0; min-width: 32px;
40	}
41	.founders-series-list .fs-title {
42	  flex: 1; font-family: var(--font-display); font-weight: 500;
43	  color: var(--fg); line-height: 1.3;
44	}
45	.founders-series-list .fs-time {
46	  font-size: .8rem; color: var(--fg-muted);
47	  font-family: var(--font-display); flex-shrink: 0;
48	}
49	.team-card { text-align: left; }
50	.team-photo { width: 100%; aspect-ratio: 1; border-radius: var(--radius-lg); margin-bottom: 16px; background: var(--bg-subtle); border: 1px solid var(--border); position: relative; overflow: hidden; display: flex; align-items: flex-end; padding: 20px; }
51	.team-photo::before { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 50%, rgba(13,4,7,.5) 100%); }
52	.team-photo .initials { position: relative; font-family: var(--font-display); font-weight: 700; font-size: 3.25rem; color: rgba(255,255,255,.9); letter-spacing: -.03em; line-height: 1; z-index: 1; }
53	.team-photo .team-photo-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
54	.team-photo.has-img .initials { display: none; }
55	.team-photo.has-img::before { z-index: 1; }
56	.team-photo.bg-1 { background: linear-gradient(135deg, #1f61ff, #4d7eff); }
57	.team-photo.bg-2 { background: linear-gradient(135deg, #e76021, #f07a3d); }
58	.team-photo.bg-3 { background: linear-gradient(135deg, #0d0407, #4a4a6a); }
59	.team-photo.bg-4 { background: linear-gradient(135deg, #1349d4, #08227a); }
60	.team-photo.bg-5 { background: linear-gradient(135deg, #f07a3d, #c04c18); }
61	.team-photo.bg-6 { background: linear-gradient(135deg, #4a4a6a, #1e1e34); }
62	.team-photo.bg-7 { background: linear-gradient(135deg, #7a9fff, #1f61ff); }
63	.team-photo.bg-8 { background: linear-gradient(135deg, #ff9f61, #e76021); }
64	.team-card h4 { font-family: var(--font-display); font-size: 1.05rem; font-weight: 700; color: var(--fg); margin-bottom: 2px; letter-spacing: -.01em; }
65	.team-card .role { font-size: .85rem; color: var(--brand); font-family: var(--font-display); font-weight: 500; margin-bottom: 8px; }
66	.team-card .bio { font-size: .84rem; color: var(--fg-muted); line-height: 1.55; }
67	
68	/* ── ABOUT MISSION ────────────────────── */
69	.about-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
70	.about-stat { background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px; text-align: left; box-shadow: var(--shadow-sm); }
71	.about-stat .n { font-family: var(--font-display); font-size: 2rem; font-weight: 700; color: var(--brand); letter-spacing: -.02em; line-height: 1; }
72	.about-stat .l { font-size: .86rem; color: var(--fg-muted); margin-top: 8px; }
73	.about-visual { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
74	
75	.timeline { position: relative; max-width: 820px; margin: 0 auto; padding: 0; }
76	.timeline::before { content: ''; position: absolute; left: 12px; top: 12px; bottom: 12px; width: 2px; background: var(--border); }
77	.tl-item { display: grid; grid-template-columns: 120px 1fr; gap: 36px; padding: 14px 0 36px 0; position: relative; }
78	.tl-item::before { content: ''; position: absolute; left: 5px; top: 22px; width: 16px; height: 16px; border-radius: 50%; background: var(--bg); border: 3px solid var(--brand); z-index: 1; }
79	.tl-year { font-family: var(--font-display); font-size: 1.35rem; font-weight: 700; color: var(--brand); letter-spacing: -.02em; padding-left: 42px; }
80	.tl-item h4 { font-family: var(--font-display); font-size: 1.1rem; font-weight: 700; color: var(--fg); margin-bottom: 6px; letter-spacing: -.01em; }
81	.tl-item p { font-size: .95rem; color: var(--fg-muted); line-height: 1.6; }
82	
