1	/*
2	 * Sight Beyond Sight — design tokens (TEWW_REDESIGN_SPEC.md §2).
3	 * Night-first: the default theme is a deep indigo night lit by saffron gold.
4	 * Variable NAMES are a stable contract shared with /ad-min — only values
5	 * change here.
6	 */
7	@font-face { font-family: 'Literata'; src: url('/fonts/Literata-Variable.ttf') format('truetype-variations'); font-weight: 200 900; font-display: swap; }
8	@font-face { font-family: 'Literata'; src: url('/fonts/Literata-Italic-Variable.ttf') format('truetype-variations'); font-weight: 200 900; font-style: italic; font-display: swap; }
9	@font-face { font-family: 'Manrope'; src: url('/fonts/Manrope-Variable.ttf') format('truetype-variations'); font-weight: 200 800; font-display: swap; }
10	
11	/*
12	 * Fallback @font-face declarations with size-adjust + ascent/descent
13	 * overrides. The browser uses these while the real font files are
14	 * downloading, so the layout doesn't shift when the swap happens
15	 * (eliminates ~0.05–0.1 of CLS per page on slow networks).
16	 */
17	@font-face {
18	  font-family: 'Literata Fallback';
19	  src: local('Georgia');
20	  size-adjust: 103%;
21	  ascent-override: 95%;
22	  descent-override: 26%;
23	  line-gap-override: 0%;
24	}
25	@font-face {
26	  font-family: 'Manrope Fallback';
27	  src: local('Arial');
28	  size-adjust: 101%;
29	  ascent-override: 97%;
30	  descent-override: 24%;
31	  line-gap-override: 0%;
32	}
33	
34	/* Tailwind utilities (shadcn/ui). Preflight is disabled in tailwind.config.js
35	   so the existing reset below remains the source of truth. */
36	@tailwind base;
37	@tailwind components;
38	@tailwind utilities;
