border: 1px solid var(--border);
border-left: 3px solid var(--brand);
border-radius: var(--radius-lg);

input.new_string:
border: 1px solid var(--border);
border-top: 2px solid var(--brand); /* gold hairline top — house elevation accent (spec §3) */
border-radius: var(--radius-lg);

input.content:
/*
 * About extras — hero motif, FAQ accordion rows, mission pull-quote,
 * board editorial list. Sight Beyond Sight (§5 About).
 */

/* ── HERO — echo-ripple motif ──────────────────── */
.about-hero { position: relative; overflow: hidden; }
.about-hero .page-hero-inner { position: relative; z-index: 1; }
/* House style: <em> in display titles = Literata italic gold. */
.about-hero h1 em { font-style: italic; }
.about-hero-ripple {
  position: absolute; top: 50%; right: -140px; transform: translateY(-50%);
  width: 620px; height: 620px; border-radius: 50%;
  pointer-events: none;
  background: repeating-radial-gradient(
    circle at center,
    color-mix(in srgb, var(--brand) 22%, transparent) 0 1px,
    transparent 1px 42px
  );
  -webkit-mask-image: radial-gradient(circle at center, #000 25%, transparent 72%);
          mask-image: radial-gradient(circle at center, #000 25%, transparent 72%);
}
/* High-contrast: no translucent decoration. */
[data-theme="high-contrast"] .about-hero-ripple { display: none; }

/* ── FAQ — 01–05 hairline rows, oversized numerals ── */
.faq-wrap { max-width: 920px; margin: 0 auto; padding: 0 var(--space-8); display: flex; flex-direction: column; }
.faq-intro-row {
  display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: end;
  margin-bottom: 40px; padding-bottom: 32px;
}
.faq-intro-row h2 {
  font-family: var(--font-display); font-weight: 600;
  font-size: clamp(1.9rem, 1.4rem + 2vw, 2.75rem);
  letter-spacing: -.015em; line-height: 1.12;
  color: var(--fg); text-wrap: balance;
}
.faq-intro-row h2 em { font-style: italic; color: var(--brand); }
.faq-intro-row p { font-size: 1.02rem; color: var(--fg-muted); line-height: 1.65; }
.faq-counter {
  font-family: var(--font-body); font-weight: 700; font-size: .72rem;
  letter-spacing: .16em; text-transform: uppercase; color: var(--brand);
  margin-bottom: 12px; display: block;
}

details.faq-item {
  border-bottom: 1px solid var(--border);
  background: transparent;
}
.faq-wrap > details.faq-item:first-of-type { border-top: 1px solid var(--about-rule); }
details.faq-item > summary {
  list-style: none; cursor: pointer;
  padding: 26px 4px;
  display: grid; grid-template-columns: 88px 1fr 44px;
  align-items: center; gap: 20px;
}
details.faq-item > summary::-webkit-details-marker { display: none; }
.faq-num {
  font-family: var(--font-display); font-weight: 330;
  font-size: clamp(2rem, 1.4rem + 2vw, 2.75rem); line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--fg-subtle);
  transition: color .2s ease;
}
details.faq-item[open] .faq-num { color: var(--brand); }
.faq-q {
  font-family: var(--font-display); font-weight: 600;
  font-size: clamp(1.15rem, 1rem + .8vw, 1.5rem);
  letter-spacing: -.015em; line-height: 1.25;
  color: var(--fg); text-wrap: balance;
}
.faq-q em { font-style: italic; color: var(--brand); }
.faq-chev {
  width: 44px; height: 44px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: transparent; color: var(--fg-muted);
  border: 1px solid var(--border);
  transition: transform .3s ease, background .2s, color .2s, border-color .2s;
  font-size: 16px;
}
details.faq-item:hover:not([open]) .faq-chev { border-color: var(--border-strong); color: var(--fg); }
details.faq-item[open] .faq-chev {
  transform: rotate(45deg);
  background: var(--brand); color: var(--brand-fg); border-color: var(--brand);
}
.faq-panel {
  padding: 0 4px 32px 108px;
  animation: faqFade .35s ease;
  font-size: 1.02rem; line-height: 1.72; color: var(--fg-muted);
  max-width: 64ch;
}
@keyframes faqFade { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) {
  .faq-panel { animation: none; }
  .faq-chev { transition: none; }
}
.faq-panel strong { color: var(--fg); font-weight: 600; }
.faq-panel em { font-style: italic; color: var(--brand); }

.faq-cta {
  margin-top: 64px; padding: 40px 44px;
  border: 1px solid var(--border);
  border-top: 2px solid var(--brand); /* gold hairline top — house elevation accent */
  border-radius: var(--radius-lg);
  background: var(--bg-elevated);
  display: flex; align-items: center; justify-content: space-between;
  gap: 24px; flex-wrap: wrap;
}
.faq-cta h3 { font-family: var(--font-display); font-size: 1.35rem; font-weight: 600; letter-spacing: -.015em; color: var(--fg); margin-bottom: 6px; }
.faq-cta p { font-size: .94rem; color: var(--fg-muted); }
.faq-cta-btns { display: flex; gap: 12px; flex-wrap: wrap; }

@media (max-width: 720px) {
  .faq-intro-row { grid-template-columns: 1fr; gap: 18px; }
  details.faq-item > summary { padding: 20px 2px; grid-template-columns: 52px 1fr 40px; gap: 14px; }
  .faq-num { font-size: 1.6rem; }
  .faq-chev { width: 40px; height: 40px; }
  .faq-panel { padding: 0 2px 26px; }
  .faq-cta { padding: 28px 24px; }
}

/* ── MISSION — Rumi pull-quote ─────────────────── */
.about-mission-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 1.3rem + 1.8vw, 2.5rem);
  font-weight: 600; letter-spacing: -.015em; line-height: 1.12;
  color: var(--fg); margin-bottom: 20px;
}
.about-mission-body { font-size: 1.05rem; color: var(--fg-muted); line-height: 1.75; margin-bottom: 16px; }
.about-mission-body em { font-style: italic; color: var(--brand); }
/* The Rumi line (first <em> in the CMS body) is the pull-quote:
   big Literata italic, gold, set off by a gold hairline. */
.about-mission-body em:first-of-type {
  display: block;
  font-family: var(--font-display);
  font-size: clamp(1.45rem, 1.1rem + 1.4vw, 2rem);
  font-weight: 560; line-height: 1.35; letter-spacing: -.01em;
  margin: 22px 0;
  padding-left: 22px;
  border-left: 1px solid var(--about-rule);
}

/* ── BOARD — editorial list ────────────────────── */
.board-card { border-top: 1px solid var(--about-rule); }
.board-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 4px;
  border-bottom: 1px solid var(--border);
}
.board-row-left { display: flex; align-items: baseline; gap: 18px; }
.board-avatar {
  min-width: 52px;
  font-family: var(--font-display); font-weight: 600; font-style: italic;
  font-size: 1.15rem; line-height: 1;
  color: var(--brand);
}
.board-name { font-family: var(--font-display); font-weight: 600; color: var(--fg); font-size: 1.02rem; letter-spacing: -.01em; }
.board-title { font-size: .85rem; color: var(--fg-muted); margin-top: 2px; }
.board-row svg { color: var(--fg-subtle); flex-shrink: 0; }
